function mascaraCNPJ(v:string){const d=String(v||'').replace(/\D/g,'').slice(0,14);return d.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\d{4})(\d)/,'$1-$2')}
function iconeEpi(n:any){const s=String(n||'').toLowerCase();if(s.includes('capacete'))return'🪖';if(s.includes('luva'))return'🧤';if(s.includes('bota')||s.includes('calçado')||s.includes('botina'))return'👢';if(s.includes('óculos'))return'👓';if(s.includes('máscara')||s.includes('mascara'))return'😷';if(s.includes('protetor'))return'🎧';return'🦺'}
function gerarPIN(){return String(Math.floor(1000+Math.random()*9000))}
function gerarSenha(){return 'Previx'+Math.floor(1000+Math.random()*9000)+'@'}
function limparData(v:any){if(!v)return'';v=String(v).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const m=v.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);if(m)return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');if(v.includes('T'))return v.split('T')[0];return''}
function fmtData(v:any){const l=limparData(v);if(!l)return'-';return l.split('-').reverse().join('/')}
function comparaData(a:any,b:any){return limparData(a.data).localeCompare(limparData(b.data))}
function statusExame(it:any){const d=limparData(it?.data);const r=String(it?.resultado||'').toLowerCase();if(r==='apto'||r==='inapto')return'realizado';if(!d)return'sem-data';const h=new Date().toISOString().split('T')[0];if(d===h)return'hoje';if(d<h)return'vencido';return'futuro'}
function statusDoc(it:any){const v=limparData(it?.vencimento);if(!v)return{label:'Sem vencimento',cor:'#64748b',bg:'#f1f5f9',emoji:'⚪'};const h=new Date();h.setHours(0,0,0,0);const ve=new Date(v+'T00:00:00');const diff=Math.ceil((ve.getTime()-h.getTime())/86400000);if(diff<0)return{label:'VENCIDO',cor:'#fff',bg:'#dc2626',emoji:'🔴'};if(diff<=30)return{label:'A VENCER - '+diff+' dias',cor:'#78350f',bg:'#fef3c7',emoji:'🟡'};return{label:'EM DIA',cor:'#fff',bg:'#16a34a',emoji:'🟢'}}
function statusExtintor(it:any){const v=limparData(it?.vencimento);if(!v)return{label:'Sem data',cor:'#e2e8f0',txt:'#475569',bg:'#f1f5f9',emoji:'⚪'};const h=new Date();h.setHours(0,0,0,0);const ve=new Date(v+'T00:00:00');const diff=Math.ceil((ve.getTime()-h.getTime())/86400000);if(diff<0)return{label:'VENCIDO',cor:'#dc2626',txt:'#fff',bg:'#fee2e2',emoji:'🔴'};if(diff<=30)return{label:'A VENCER - '+diff+' dias',cor:'#f59e0b',txt:'#78350f',bg:'#fef3c7',emoji:'🟡'};return{label:'EM DIA - '+diff+' dias',cor:'#16a34a',txt:'#fff',bg:'#dcfce7',emoji:'🟢'}}
function iconeArquivo(n:string){const s=String(n||'').toLowerCase();if(s.endsWith('.pdf'))return'📕';if(s.endsWith('.doc')||s.endsWith('.docx'))return'📘';if(s.endsWith('.xls')||s.endsWith('.xlsx'))return'📗';if(s.endsWith('.jpg')||s.endsWith('.jpeg')||s.endsWith('.png'))return'🖼️';return'📄'}
