{aba==='inspecoes' && (<div style={{marginTop:16,display:'flex',gap:8,flexWrap:'wrap'}}><button onClick={()=>setFiltroInsp('Todos')} style={{...btn,background:filtroInsp==='Todos'?'#0f172a':'#f1f5f9',color:filtroInsp==='Todos'?'white':'#0f172a',borderRadius:20}}>Todos ({inspF.length})</button>{TIPOS_INSPECAO.map(t=>{const q=inspF.filter((x:any)=>(x.tipoInspecao||x.tipo)===t.id).length;return <button key={t.id} onClick={()=>setFiltroInsp(t.id)} style={{...btn,background:filtroInsp===t.id?'#0d9488':'#f1f5f9',color:filtroInsp===t.id?'white':'#0f172a',borderRadius:20}}>{t.id} ({q})</button>})}</div>)}
{aba==='documentos' && (<div style={{marginTop:16}}><div style={{display:'flex',gap:8,flexWrap:'wrap'}}><button onClick={()=>{setPastaAtual('Todas');setFiltroDoc('Todos')}} style={{...btn,background:pastaAtual==='Todas'?'#0d9488':'#f1f5f9',color:pastaAtual==='Todas'?'white':'#0f172a',borderRadius:20}}>Todas ({docsF.length})</button>{PASTAS.map(p=>{const q=docsF.filter((d:any)=>(d.pasta||d.tipo)===p.id).length;return <button key={p.id} onClick={()=>setPastaAtual(p.id)} style={{...btn,background:pastaAtual===p.id?'#0d9488':'#f1f5f9',color:pastaAtual===p.id?'white':'#0f172a',borderRadius:20}}>{p.nome} ({q})</button>})}</div><div style={{display:'flex',gap:8,flexWrap:'wrap',marginTop:10}}><button onClick={()=>setFiltroDoc('Todos')} style={{...btn,background:'#f1f5f9',borderRadius:20}}>Todos</button><button onClick={()=>setFiltroDoc('Vencido')} style={{...btn,background:'#fee2e2',borderRadius:20}}>🔴 Vencido ({qDocVenc})</button><button onClick={()=>setFiltroDoc('A Vencer')} style={{...btn,background:'#fef3c7',borderRadius:20}}>🟡 A Vencer ({qDocAvencer})</button><button onClick={()=>setFiltroDoc('Em Dia')} style={{...btn,background:'#dcfce7',borderRadius:20}}>🟢 Em Dia ({qDocDia})</button></div></div>)}
{aba==='extintores' && (<div style={{marginTop:16,display:'flex',gap:8,flexWrap:'wrap'}}><button onClick={()=>setFiltroExt('Todos')} style={{...btn,background:'#f1f5f9',borderRadius:20}}>Todos ({extsF.length})</button><button onClick={()=>setFiltroExt('Vencido')} style={{...btn,background:'#fee2e2',borderRadius:20}}>🔴 Vencido ({qExtVenc})</button><button onClick={()=>setFiltroExt('A Vencer')} style={{...btn,background:'#fef3c7',borderRadius:20}}>🟡 A Vencer ({qExtAvencer})</button><button onClick={()=>setFiltroExt('Em Dia')} style={{...btn,background:'#dcfce7',borderRadius:20}}>🟢 Em Dia ({qExtDia})</button></div>)}
{aba==='riscos' && (<div style={{background:'#fef9c3',borderRadius:16,padding:16,marginTop:16}}><b>Cadastra 1x, gera 3 laudos</b><div style={{display:'flex',gap:8,flexWrap:'wrap',marginTop:10}}><button onClick={()=>gerarLaudo('PGR')} style={{...btn,background:'#0d9488',color:'white',borderRadius:20}}>Gerar PGR</button><button onClick={()=>gerarLaudo('LTCAT')} style={{...btn,background:'#2563eb',color:'white',borderRadius:20}}>Gerar LTCAT</button><button onClick={()=>gerarLaudo('LIP')} style={{...btn,background:'#f59e0b',color:'white',borderRadius:20}}>Gerar LIP</button><button onClick={()=>gerarLaudo('PCMSO')} style={{...btn,background:'#22c55e',color:'white',borderRadius:20}}>Gerar PCMSO</button></div></div>)}
{aba==='funcionarios' && (<div style={{display:'flex',gap:8,flexWrap:'wrap',marginTop:16}}>{['Todos',...SETORES].map(s=>{const q=s==='Todos'?funcs.length:funcs.filter((f:any)=>f.setor===s).length;if(q===0&&s!=='Todos')return null;return <button key={s} onClick={()=>setFiltroSetor(s)} style={{...btn,background:filtroSetor===s?'#0d9488':'#f1f5f9',color:filtroSetor===s?'white':'#0f172a',borderRadius:20}}>{s} ({q})</button>})}</div>)}
{aba==='epis' && (<div style={{marginTop:16}}><input placeholder="Buscar EPI por funcionário, CPF ou nome..." value={buscaEpi} onChange={e=>setBuscaEpi(e.target.value)} style={{...input}} /></div>)}
